import type { Parser } from "./parser.js";
import { statePrint } from "./debug.js";

/**
 * Zero-copy span: stores start/end offsets into the source string.
 * Call toString(src) for lazy materialization of the substring.
 */
export interface Span {
    start: number;
    end: number;
}

export function spanToString(span: Span, src: string): string {
    return src.substring(span.start, span.end);
}

export function mergeSpans(a: Span, b: Span): Span {
    return { start: a.start, end: b.end };
}

// ── Diagnostic substate types ────────────────────────────────
// These live with ParserState because the diagnostic accumulator is per-parse
// state, threaded through the parse, not a module global.

export interface Suggestion {
    kind: "unclosed-delimiter" | "trailing-content";
    message: string;
    openOffset?: number;
}

export interface SecondarySpan {
    offset: number;
    label: string;
}

export interface Diagnostic {
    offset: number;
    furthestOffset: number;
    line: number;
    column: number;
    expected: string[];
    suggestions: Suggestion[];
    secondarySpans: SecondarySpan[];
    found: string;
}

type ParserFault =
    | Readonly<{ kind: "Nesting"; offset: number; limit: number }>
    | Readonly<{ kind: "RecoveryNonProgress"; offset: number }>;

const NESTING_LIMIT = 256;

export class ParserState<T = unknown> {
    /**
     * Furthest-offset error tracking, threaded per-parse (the Rust port's
     * `state.furthest_offset` model). `expected` is the accumulated label set
     * at `furthest`; `suggestions`/`secondarySpans` are the diagnostic extras
     * collected at `furthest` when diagnostics are enabled.
     */
    expected?: string[];
    suggestions: Suggestion[] = [];
    secondarySpans: SecondarySpan[] = [];
    diagnostics: Diagnostic[] = [];
    fault: ParserFault | undefined = undefined;
    liveDepth = 0;
    maxDepth = 0;

    constructor(
        public src: string,
        public value: T = undefined as T,
        public offset: number = 0,
        public isError: boolean = false,
        public furthest: number = -1,
    ) {}

    ok<S>(value: S, offset: number = 0): ParserState<S> {
        this.offset += offset;
        this.unsafeSetValue(value);
        this.isError = this.fault !== undefined;
        return this as unknown as ParserState<S>;
    }

    err<S>(value?: S, offset: number = 0): ParserState<S> {
        this.offset += offset;
        this.unsafeSetValue(value);
        this.isError = true;
        return this as unknown as ParserState<S>;
    }

    from<S>(value: S, offset: number = 0): ParserState<S> {
        this.offset += offset;
        this.unsafeSetValue(value);
        return this as unknown as ParserState<S>;
    }

    rollback(
        offset: number,
        value: T,
        diagnosticsLength: number,
        isError: boolean,
    ): this {
        if (this.offset !== offset) this.offset = offset;
        if (this.value !== value) this.value = value;
        if (this.diagnostics.length !== diagnosticsLength) {
            this.diagnostics.length = diagnosticsLength;
        }
        this.isError = isError || this.fault !== undefined;
        return this;
    }

    enterLazy(): boolean {
        if (this.liveDepth >= NESTING_LIMIT) {
            this.fault ??= {
                kind: "Nesting",
                offset: this.offset,
                limit: NESTING_LIMIT,
            };
            this.isError = true;
            return false;
        }
        this.liveDepth++;
        this.maxDepth = Math.max(this.maxDepth, this.liveDepth);
        return true;
    }

    leaveLazy(): void {
        this.liveDepth--;
    }

    /** Type-erased value setter — single choke point for the mutable-state cast pattern. */
    unsafeSetValue(value: unknown): void {
        (this as ParserState<unknown>).value = value as T;
    }

    /** Type-erased parser invocation via .call() — single choke point for combinator type casts. */
    unsafeCall(parser: Parser<unknown>): void {
        parser.call(this as ParserState<unknown>);
    }

    /** Type-erased raw parser invocation via .parser() — for internal combinator plumbing. */
    unsafeCallRaw(parser: Parser<unknown>): void {
        parser.parser(this as ParserState<unknown>);
    }

    clone(): ParserState<T> {
        const clone = new ParserState<T>(
            this.src,
            this.value,
            this.offset,
            this.isError,
            this.furthest,
        );
        clone.expected = this.expected ? [...this.expected] : undefined;
        clone.suggestions = [...this.suggestions];
        clone.secondarySpans = [...this.secondarySpans];
        clone.diagnostics = [...this.diagnostics];
        clone.fault = this.fault;
        clone.liveDepth = this.liveDepth;
        clone.maxDepth = this.maxDepth;
        return clone;
    }

    getColumnNumber(): number {
        const offset = this.offset;
        const lastNewline = this.src.lastIndexOf("\n", offset);
        const columnNumber =
            lastNewline === -1 ? offset : offset - (lastNewline + 1);
        return Math.max(0, columnNumber);
    }

    getLineNumber(): number {
        const newlineIndex = this.src.lastIndexOf("\n", this.offset);
        return newlineIndex >= 0
            ? this.src.slice(0, newlineIndex).split("\n").length
            : 0;
    }

    /** Returns 1-based line and 0-based column for any offset. */
    getLineAndColumn(offset: number = this.offset): { line: number; column: number } {
        const lastNewline = this.src.lastIndexOf("\n", offset - 1);
        const line = lastNewline === -1
            ? 1
            : this.src.slice(0, lastNewline + 1).split("\n").length;
        const column = lastNewline === -1 ? offset : offset - lastNewline - 1;
        return { line, column };
    }

    toString() {
        return statePrint(this as ParserState<unknown>);
    }
}

export const parserNames = [
    "string",
    "regex",
    "then",
    "or",
    "chain",
    "map",
    "many",
    "lazy",
    "memoize",
    "mergeMemo",
    "not",
    "minus",
    "skip",
    "next",
    "trim",
    "trimWhitespace",
    "whitespace",
    "wrap",
    "sepBy",
    "any",
    "all",
    "opt",
    "eof",
    "dispatch",
    "debug",
    "mapState",
    "recover",
    "peek",
    "lookAhead",
] as const;

export type ParserContext = {
    name?: (typeof parserNames)[number];
    parser?: Parser<unknown>;
    args?: unknown[];
};

export function createParserContext(
    name: (typeof parserNames)[number],
    parser: Parser<unknown> | undefined,
    ...args: unknown[]
) {
    return {
        name,
        parser,
        args,
    };
}
